+// Modal Dialog Component
+class DeleteConfirmationModal {
+    constructor() {
+        this.modal = document.getElementById('deleteModal');
+        this.backdrop = this.modal.querySelector('.modal-backdrop');
+        this.closeBtn = this.modal.querySelector('.modal-close');
+        this.cancelBtn = this.modal.querySelector('.modal-cancel');
+        this.confirmBtn = this.modal.querySelector('.modal-confirm');
+        this.currentImageId = null;
+
+        this.init();
+    }
+
+    init() {
+        // Attach event listeners
+        this.closeBtn.addEventListener('click', () => this.close());
+        this.backdrop.addEventListener('click', () => this.close());
+        this.cancelBtn.addEventListener('click', () => this.close());
+        this.confirmBtn.addEventListener('click', () => this.handleDelete());
+
+        // Attach listeners to all trigger buttons
+        const triggerButtons = document.querySelectorAll('.trigger');
+        triggerButtons.forEach((btn) => {
+            btn.addEventListener('click', (e) => this.handleTrigger(e));
+        });
+
+        // Close on Escape key
+        document.addEventListener('keydown', (e) => {
+            if (e.key === 'Escape' && this.isOpen()) {
+                this.close();
+            }
+        });
+    }
+
+    handleTrigger(event) {
+        const button = event.target.closest('.trigger');
+        this.currentImageId = button.getAttribute('data-image-id');
+        this.open();
+    }
+
+    open() {
+        this.modal.classList.add('active');
+        this.modal.setAttribute('aria-hidden', 'false');
+        document.body.style.overflow = 'hidden';
+    }
+
+    close() {
+        this.modal.classList.remove('active');
+        this.modal.setAttribute('aria-hidden', 'true');
+        document.body.style.overflow = '';
+        this.currentImageId = null;
+    }
+
+    isOpen() {
+        return this.modal.classList.contains('active');
+    }
+
+    handleDelete() {
+        if (this.currentImageId) {
+            console.log(`Image deleted: ${this.currentImageId}`);
+            // Find and remove the image card
+            const imageCard = document.querySelector(
+                `[data-image-id="${this.currentImageId}"]`
+            ).closest('.image-card');
+
+            // Animate removal
+            imageCard.style.animation = 'slideDown 0.3s ease forwards';
+            setTimeout(() => {
+                imageCard.remove();
+                this.close();
+            }, 300);
+        }
+    }
+}
+
+// Initialize on DOM ready
+document.addEventListener('DOMContentLoaded', () => {
+    new DeleteConfirmationModal();
+});
+
+// Add slide down animation for removal
+const style = document.createElement('style');
+style.textContent = `
+    @keyframes slideDown {
+        from {
+            opacity: 1;
+            transform: translateY(0);
+        }
+        to {
+            opacity: 0;
+            transform: translateY(20px);
+        }
+    }
+`;
+document.head.appendChild(style);
+
