+/* Accessibility */
+.modal[aria-hidden="false"] {
+    display: flex;
+}
+
+.modal[aria-hidden="true"] {
+    display: none;
+}
+
+/* Responsive */
+@media (max-width: 768px) {
+    .header {
+        padding: 32px 16px;
+        margin-bottom: 24px;
+    }
+
+    .header h1 {
+        font-size: 24px;
+    }
+
+    .gallery {
+        grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
